W, c0 = 17, 8
out = [[0]*W for _ in range(W)]
for r in range(W):
    if 0 <= c0 - r < W: out[r][c0-r] = 2
    if 0 <= c0 + r < W: out[r][c0+r] = 2
for r in range(W):
    for c in range(W):
        if r+c > c0 and r-c > -c0 and (r-c) % 4 == (-c0) % 4:
            out[r][c] = 1
for row in out: print(' '.join(map(str,row)))
